1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Tetris</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  [hidden] { display: none !important; }
10	  body {
11	    margin: 0;
12	    min-height: 100vh;
13	    display: flex;
14	    align-items: center;
15	    justify-content: center;
16	    background: #111827;
17	    color: #e5e7eb;
18	    font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
19	  }
20	  .game { display: flex; gap: 24px; align-items: flex-start; padding: 16px; }
21	  .board-wrap { position: relative; }
22	  .board {
23	    display: grid;
24	    grid-template-columns: repeat(10, 28px);
25	    grid-template-rows: repeat(20, 28px);
26	    gap: 1px;
27	    padding: 1px;
28	    background: #1f2937;
29	    border: 2px solid #374151;
30	  }
31	  .cell { width: 28px; height: 28px; background-color: #0b1020; }
32	  .mini {
33	    display: grid;
34	    grid-template-columns: repeat(4, 16px);
35	    grid-template-rows: repeat(2, 16px);
36	    gap: 1px;
37	  }
38	  .mini-cell { width: 16px; height: 16px; background-color: transparent; }
39	  .p-I { background-color: #22d3ee; }
40	  .p-O { background-color: #facc15; }
41	  .p-T { background-color: #a855f7; }
42	  .p-S { background-color: #22c55e; }
43	  .p-Z { background-color: #ef4444; }
44	  .p-J { background-color: #3b82f6; }
45	  .p-L { background-color: #f97316; }
46	  .panel { width: 160px; }
47	  .stat { margin-bottom: 14px; }
48	  .stat .label { font-size: 12px; text-transform: uppercase; letter-spacing: 0.08em; color: #9ca3af; }
49	  .stat .value { font-size: 24px; font-weight: 600; font-variant-numeric: tabular-nums; }
50	  .help { font-size: 12px; color: #9ca3af; line-height: 1.6; margin-top: 12px; }
51	  .overlay {
52	    position: absolute;
53	    inset: 0;
54	    display: flex;
55	    flex-direction: column;
56	    align-items: center;
57	    justify-content: center;
58	    background: rgba(17, 24, 39, 0.8);
59	    font-size: 22px;
60	    font-weight: 600;
61	  }
62	  .overlay small { font-size: 13px; font-weight: 400; margin-top: 8px; color: #d1d5db; }
63	</style>
64	</head>
65	<body>
66	<div class="game">
67	  <div class="board-wrap">
68	    <div class="board" id="board" data-testid="board"></div>
69	    <div class="overlay" id="overlay" data-testid="game-over" hidden>Game over<small>Press Enter to play again</small></div>
70	  </div>
71	  <div class="panel">
72	    <div class="stat"><div class="label">Score</div><div class="value" data-testid="score" id="score">0</div></div>
73	    <div class="stat"><div class="label">Level</div><div class="value" data-testid="level" id="level">1</div></div>
74	    <div class="stat"><div class="label">Lines</div><div class="value" data-testid="lines" id="lines">0</div></div>
75	    <div class="stat"><div class="label">Next</div><div id="next" data-testid="next-piece"></div></div>
76	    <div class="stat"><div class="label">Hold</div><div id="hold" class="mini" data-testid="hold-piece" data-piece=""></div></div>
77	    <div class="help">
78	      ← → move<br>
79	      ↑ rotate<br>
80	      ↓ soft drop<br>
81	      Space hard drop<br>
82	      C hold<br>
83	      Enter new game
84	    </div>
85	  </div>
86	</div>
87	<script>
88	(function () {
89	  "use strict";
90	
91	  var ROWS = 20;
92	  var COLS = 10;
93	  var PREVIEW = 1; // [REQ-006] show only the next piece
94	  var TYPES = ["I", "O", "T", "S", "Z", "J", "L"];
95	
96	  // Spawn orientation of each piece inside its rotation box.
97	  var SHAPES = {
98	    I: ["....", "IIII", "....", "...."],
99	    O: ["OO", "OO"],
100	    T: [".T.", "TTT", "..."],
101	    S: [".SS", "SS.", "..."],
102	    Z: ["ZZ.", ".ZZ", "..."],
103	    J: ["J..", "JJJ", "..."],
104	    L: ["..L", "LLL", "..."]
105	  };
106	
107	  // Scoring (decision): points for rows cleared at once, times level. Clearing rows
108	  // together always beats clearing them one at a time. Soft drop 1 per cell, hard drop 2.
109	  var LINE_POINTS = [0, 100, 300, 500, 800];
110	  var SOFT_DROP_POINTS = 1;
111	  var HARD_DROP_POINTS = 2;
112	
113	  var state = {
114	    board: [],      // ROWS arrays of COLS chars: "." or a piece letter
115	    current: null,  // { type, matrix, row, col }
116	    next: [],
117	    bag: [],
118	    score: 0,
119	    level: 1,
120	    lines: 0,
121	    hold: null,     // letter of the held piece, or null
122	    canHold: true,  // false once the current piece has used its hold
123	    status: "running"
124	  };
125	
126	  var timer = null;
127	
128	  // ---------- pieces ----------
129	
130	  function isType(t) { return TYPES.indexOf(t) !== -1; }
131	
132	  function randomType() {
133	    if (state.bag.length === 0) {
134	      var bag = TYPES.slice();
135	      for (var i = bag.length - 1; i > 0; i--) {
136	        var j = Math.floor(Math.random() * (i + 1));
137	        var tmp = bag[i]; bag[i] = bag[j]; bag[j] = tmp;
138	      }
139	      state.bag = bag;
140	    }
141	    return state.bag.pop();
142	  }
143	
144	  function cleanQueue(queue) {
145	    if (!Array.isArray(queue)) return [];
146	    return queue.map(function (t) { return String(t).toUpperCase(); }).filter(isType);
147	  }
148	
149	  function fillPreview() {
150	    while (state.next.length < PREVIEW) state.next.push(randomType());
151	  }
152	
153	  function makeMatrix(type) {
154	    return SHAPES[type].map(function (r) { return r.split(""); });
155	  }
156	
157	  function pieceCells(piece) {
158	    var cells = [];
159	    for (var r = 0; r < piece.matrix.length; r++) {
160	      for (var c = 0; c < piece.matrix[r].length; c++) {
161	        if (piece.matrix[r][c] !== ".") cells.push([piece.row + r, piece.col + c]);
162	      }
163	    }
164	    return cells;
165	  }
166	
167	  function fits(matrix, row, col) {
168	    for (var r = 0; r < matrix.length; r++) {
169	      for (var c = 0; c < matrix[r].length; c++) {
170	        if (matrix[r][c] === ".") continue;
171	        var br = row + r, bc = col + c;
172	        if (br < 0 || br >= ROWS || bc < 0 || bc >= COLS) return false;
173	        if (state.board[br][bc] !== ".") return false;
174	      }
175	    }
176	    return true;
177	  }
178	
179	  // [REQ-001] [REQ-004] [REQ-007] Spawn the next piece, or the given one (from hold);
180	  // the game ends if it has nowhere to go.
181	  function spawn(fromHold) {
182	    var type = fromHold || (state.next.length ? state.next.shift() : randomType());
183	    fillPreview();
184	    var matrix = makeMatrix(type);
185	    var top = 0;
186	    while (matrix[top].every(function (ch) { return ch === "."; })) top++;
187	    var piece = {
188	      type: type,
189	      matrix: matrix,
190	      row: -top,
191	      col: Math.floor((COLS - matrix[0].length) / 2),
192	      lockTicks: 0,
193	      lockResets: 0
194	    };
195	    if (!fits(piece.matrix, piece.row, piece.col)) {
196	      state.current = null;
197	      state.status = "gameover";
198	      stopTimer();
199	      return;
200	    }
201	    state.current = piece;
202	  }
203	
204	  // ---------- core rules ----------
205	
206	  // [REQ-003] [REQ-007] Remove full rows, drop the rest, score by rows cleared at once times
207	  // level. The level rises by one each time the line total crosses a multiple of 10, so it
208	  // carries on from a level set by setLevel and never goes down.
209	  function clearLines() {
210	    var kept = state.board.filter(function (row) {
211	      return row.some(function (ch) { return ch === "."; });
212	    });
213	    var cleared = ROWS - kept.length;
214	    while (kept.length < ROWS) kept.unshift(emptyRow());
215	    state.board = kept;
216	    if (cleared > 0) {
217	      state.score += LINE_POINTS[cleared] * state.level;
218	      var before = Math.floor(state.lines / 10);
219	      state.lines += cleared;
220	      state.level += Math.floor(state.lines / 10) - before;
221	    }
222	  }
223	
224	  // [REQ-001] Lock the falling piece into the board, clear lines, spawn the next one.
225	  function lockPiece() {
226	    var p = state.current;
227	    pieceCells(p).forEach(function (cell) {
228	      state.board[cell[0]][cell[1]] = p.type;
229	    });
230	    state.current = null;
231	    state.canHold = true;
232	    clearLines();
233	    spawn();
234	  }
235	
236	  // [REQ-007] Hold: put the falling piece aside and take the next one, or swap with the
237	  // held piece. Once per piece until a piece locks.
238	  function hold() {
239	    if (!state.canHold) return;
240	    var type = state.current.type;
241	    var held = state.hold;
242	    state.hold = type;
243	    state.canHold = false;
244	    state.current = null;
245	    spawn(held);
246	  }
247	
248	  function tryMove(dr, dc) {
249	    var p = state.current;
250	    if (!p || !fits(p.matrix, p.row + dr, p.col + dc)) return false;
251	    p.row += dr;
252	    p.col += dc;
253	    return true;
254	  }
255	
256	  // Lock rule (DEC): a gravity step that cannot move the piece down counts one tick of
257	  // lock delay; the piece locks on the LOCK_DELAY-th such tick. A left/right move while
258	  // resting restarts the delay, at most MAX_LOCK_RESETS times per piece. A soft drop on a
259	  // resting piece restarts it too, from the same budget.
260	  var LOCK_DELAY = 2;
261	  var MAX_LOCK_RESETS = 3;
262	
263	  function isResting(p) {
264	    return !fits(p.matrix, p.row + 1, p.col);
265	  }
266	
267	  // [REQ-002] [REQ-005] Restart the lock delay if the piece has restarts left.
268	  function restartLockDelay(p) {
269	    if (p.lockResets < MAX_LOCK_RESETS) {
270	      p.lockResets++;
271	      p.lockTicks = 0;
272	    }
273	  }
274	
275	  // [REQ-002] One gravity step: fall one row, or count a tick of lock delay.
276	  // Used by the real timer, by tick(n) and by soft drop. Returns true if the piece fell.
277	  function gravityStep() {
278	    if (state.status !== "running" || !state.current) return false;
279	    var p = state.current;
280	    if (tryMove(1, 0)) {
281	      p.lockTicks = 0;
282	      return true;
283	    }
284	    p.lockTicks++;
285	    if (p.lockTicks >= LOCK_DELAY) lockPiece();
286	    return false;
287	  }
288	
289	  // [REQ-002] Sideways move; restarts the lock delay if the piece was resting.
290	  function shift(dc) {
291	    var p = state.current;
292	    var resting = isResting(p);
293	    if (!tryMove(0, dc)) return;
294	    if (resting) restartLockDelay(p);
295	  }
296	
297	  // [REQ-003] [REQ-005] Soft drop: fall one row for a point. On a resting piece it scores
298	  // nothing and restarts the lock delay like a sideways move, instead of counting a tick.
299	  function softDrop() {
300	    var p = state.current;
301	    if (isResting(p)) {
302	      restartLockDelay(p);
303	      return;
304	    }
305	    tryMove(1, 0);
306	    p.lockTicks = 0;
307	    state.score += SOFT_DROP_POINTS;
308	  }
309	
310	  // [REQ-002] Clockwise rotation with sideways kicks; refused if nothing fits.
311	  function rotate() {
312	    var p = state.current;
313	    if (!p) return;
314	    var size = p.matrix.length;
315	    var rotated = [];
316	    for (var r = 0; r < size; r++) {
317	      rotated.push([]);
318	      for (var c = 0; c < size; c++) rotated[r].push(p.matrix[size - 1 - c][r]);
319	    }
320	    var kicks = [0, -1, 1, -2, 2];
321	    for (var i = 0; i < kicks.length; i++) {
322	      if (fits(rotated, p.row, p.col + kicks[i])) {
323	        p.matrix = rotated;
324	        p.col += kicks[i];
325	        return;
326	      }
327	    }
328	  }
329	
330	  // [REQ-001] [REQ-003] Player actions; soft and hard drop score per cell moved down.
331	  function input(action) {
332	    if (state.status !== "running" || !state.current) return;
333	    switch (action) {
334	      case "left": shift(-1); break;
335	      case "right": shift(1); break;
336	      case "softDrop": softDrop(); break;
337	      case "hardDrop":
338	        var dropped = 0;
339	        while (tryMove(1, 0)) dropped++;
340	        state.score += dropped * HARD_DROP_POINTS;
341	        lockPiece();
342	        break;
343	      case "rotate":
344	      case "rotateCW": rotate(); break;
345	      case "hold": hold(); break;
346	      default: return;
347	    }
348	    render();
349	    restartTimerIfNeeded();
350	  }
351	
352	  // ---------- timer ----------
353	
354	  // [REQ-007]
355	  function gravityInterval() {
356	    return Math.max(100, 1000 - (state.level - 1) * 100);
357	  }
358	
359	  function stopTimer() {
360	    if (timer !== null) { clearTimeout(timer); timer = null; }
361	  }
362	
363	  function startTimer() {
364	    stopTimer();
365	    if (state.status !== "running") return;
366	    timer = setTimeout(function () {
367	      timer = null;
368	      gravityStep();
369	      render();
370	      startTimer();
371	    }, gravityInterval());
372	  }
373	
374	  function restartTimerIfNeeded() {
375	    if (state.status === "running" && timer === null) startTimer();
376	  }
377	
378	  // ---------- setup ----------
379	
380	  function emptyRow() {
381	    var row = [];
382	    for (var c = 0; c < COLS; c++) row.push(".");
383	    return row;
384	  }
385	
386	  // [REQ-001] Start a fresh game, optionally with a fixed piece order.
387	  function newGame(queue) {
388	    state.board = [];
389	    for (var r = 0; r < ROWS; r++) state.board.push(emptyRow());
390	    state.bag = [];
391	    state.score = 0;
392	    state.level = 1;
393	    state.lines = 0;
394	    state.hold = null;
395	    state.canHold = true;
396	    state.status = "running";
397	    state.current = null;
398	    state.next = cleanQueue(queue);
399	    fillPreview();
400	    spawn();
401	    render();
402	    startTimer();
403	  }
404	
405	  // ---------- rendering (synchronous) ----------
406	
407	  var boardEl = document.getElementById("board");
408	  var nextEl = document.getElementById("next");
409	  var holdEl = document.getElementById("hold");
410	  var scoreEl = document.getElementById("score");
411	  var levelEl = document.getElementById("level");
412	  var linesEl = document.getElementById("lines");
413	  var overlayEl = document.getElementById("overlay");
414	  var cellEls = [];
415	
416	  (function buildBoard() {
417	    for (var r = 0; r < ROWS; r++) {
418	      cellEls.push([]);
419	      for (var c = 0; c < COLS; c++) {
420	        var el = document.createElement("div");
421	        el.className = "cell";
422	        el.setAttribute("data-testid", "cell");
423	        el.setAttribute("data-row", String(r));
424	        el.setAttribute("data-col", String(c));
425	        el.setAttribute("data-filled", "false");
426	        el.setAttribute("data-piece", "");
427	        boardEl.appendChild(el);
428	        cellEls[r].push(el);
429	      }
430	    }
431	  })();
432	
433	  function paintCell(el, type) {
434	    el.className = type ? "cell p-" + type : "cell";
435	    el.setAttribute("data-filled", type ? "true" : "false");
436	    el.setAttribute("data-piece", type || "");
437	  }
438	
439	  // [REQ-004] [REQ-007] Fill a 4x2 mini grid with a piece (or leave it empty), board colours.
440	  function fillMini(grid, type) {
441	    grid.textContent = "";
442	    grid.setAttribute("data-piece", type || "");
443	    var rows = type ? SHAPES[type].filter(function (r) { return r.indexOf(type) !== -1; }) : [];
444	    for (var r = 0; r < 2; r++) {
445	      for (var c = 0; c < 4; c++) {
446	        var cell = document.createElement("div");
447	        var ch = rows[r] ? rows[r].charAt(c) : ".";
448	        cell.className = type && ch === type ? "mini-cell p-" + type : "mini-cell";
449	        grid.appendChild(cell);
450	      }
451	    }
452	  }
453	
454	  // [REQ-004] [REQ-006] The next piece only, coloured as on the board.
455	  function renderPreview() {
456	    nextEl.textContent = "";
457	    state.next.slice(0, PREVIEW).forEach(function (type) {
458	      var grid = document.createElement("div");
459	      grid.className = "mini";
460	      grid.setAttribute("data-testid", "next-piece-item");
461	      fillMini(grid, type);
462	      nextEl.appendChild(grid);
463	    });
464	  }
465	
466	  // [REQ-001] Draw the whole game state into the DOM, immediately.
467	  function render() {
468	    var drawn = state.board.map(function (row) { return row.slice(); });
469	    if (state.current) {
470	      var type = state.current.type;
471	      pieceCells(state.current).forEach(function (cell) {
472	        drawn[cell[0]][cell[1]] = type;
473	      });
474	    }
475	    for (var r = 0; r < ROWS; r++) {
476	      for (var c = 0; c < COLS; c++) {
477	        var ch = drawn[r][c];
478	        paintCell(cellEls[r][c], ch === "." ? "" : ch);
479	      }
480	    }
481	    scoreEl.textContent = String(state.score);
482	    levelEl.textContent = String(state.level);
483	    linesEl.textContent = String(state.lines);
484	    overlayEl.hidden = state.status !== "gameover";
485	    renderPreview();
486	    fillMini(holdEl, state.hold);
487	  }
488	
489	  // ---------- keyboard ----------
490	
491	  document.addEventListener("keydown", function (e) {
492	    var map = {
493	      ArrowLeft: "left",
494	      ArrowRight: "right",
495	      ArrowDown: "softDrop",
496	      ArrowUp: "rotateCW",
497	      " ": "hardDrop",
498	      c: "hold",
499	      C: "hold",
500	      Shift: "hold"
501	    };
502	    if (e.key === "Enter") {
503	      e.preventDefault();
504	      newGame();
505	      return;
506	    }
507	    if (map[e.key]) {
508	      e.preventDefault();
509	      input(map[e.key]);
510	    }
511	  });
512	
513	  // ---------- test control surface ----------
514	
515	  // [REQ-001]
516	  window.__tetris = {
517	    newGame: function (queue) { newGame(queue); },
518	    setQueue: function (queue) {
519	      state.next = cleanQueue(queue);
520	      fillPreview();
521	      render();
522	    },
523	    setBoard: function (rows) {
524	      var board = [];
525	      for (var r = 0; r < ROWS; r++) {
526	        var line = rows && typeof rows[r] === "string" ? rows[r] : "";
527	        var row = [];
528	        for (var c = 0; c < COLS; c++) {
529	          var ch = line.charAt(c);
530	          row.push(isType(ch) ? ch : ".");
531	        }
532	        board.push(row);
533	      }
534	      state.board = board;
535	      render();
536	    },
537	    tick: function (n) {
538	      var steps = n === undefined ? 1 : n;
539	      for (var i = 0; i < steps; i++) gravityStep();
540	      render();
541	    },
542	    input: function (action) { input(action); },
543	    // [REQ-007] Set the level for testing; levelling from lines carries on from here.
544	    setLevel: function (n) {
545	      var level = Math.floor(Number(n));
546	      if (!(level >= 1)) return;
547	      state.level = level;
548	      render();
549	      if (timer !== null) startTimer();
550	    },
551	    getBoard: function () {
552	      return state.board.map(function (row) { return row.join(""); });
553	    },
554	    getState: function () {
555	      return {
556	        current: state.current
557	          ? { type: state.current.type, cells: pieceCells(state.current) }
558	          : null,
559	        next: state.next.slice(),
560	        score: state.score,
561	        level: state.level,
562	        lines: state.lines,
563	        hold: state.hold,
564	        dropInterval: gravityInterval(),
565	        status: state.status
566	      };
567	    }
568	  };
569	
570	  newGame();
571	})();
572	</script>
573	</body>
574	</html>
